                    projectionBody: '<p>كل خريطة للعالم تواجه مشكلة مستحيلة الحل: الأرض كروية، والخريطة مسطحة. وأي محاولة لتسطيح الكرة الأرضية تشوّه شيئاً ما بالضرورة — إما الحجم، أو الشكل، أو المسافة، أو الاتجاه. فلا يوجد إسقاط جغرافي واحد يحافظ على هذه العناصر الأربعة معاً بدقة كاملة.</p><p><strong>الإسقاط الذي تراه أمامك</strong> ابتكره عام 1996 الرياضي ستيف واترمان، مستفيداً من أبحاثه في هندسة الكرات المتراصة. وتقوم فكرته على مفهوم طرحه المعماري برنارد كاهيل عام 1909، عُرف حينها بـ"خريطة الفراشة". يفتح إسقاط واترمان الكرة الأرضية عند خطوط اختيرت بعناية لتمر عبر المحيطات لا عبر القارات، فتبقى اليابسة متصلة وغير مجزأة.</p><p><strong>لماذا لا نعتمد الخريطة المألوفة؟</strong> إسقاط ميركاتور (1569) ما زال الأكثر استخداماً حتى اليوم، وهو ممتاز لغرض واحد: الحفاظ على اتجاهات البوصلة، ما جعله أساسياً للملاحة البحرية طوال قرون. لكنه يدفع ثمناً باهظاً لذلك: كلما ابتعدنا عن خط الاستواء، تضخّم الحجم النسبي للمناطق بشكل كبير. فعلى خريطة ميركاتور تبدو غرينلاند بحجم أفريقيا تقريباً، بينما أفريقيا في الواقع أكبر منها بنحو 14 مرة. وهذا خلل جوهري لأداة تعليمية يُفترض أن تعطي صورة واقعية عن العالم.</p><p><strong>ولماذا هذا الإسقاط تحديداً؟</strong> بعض الإسقاطات، مثل "غال-بيترز"، تصحح مشكلة الحجم لكنها تشوّه الأشكال بدلاً من ذلك، فتبدو القارات ممطوطة وغير مألوفة. أما إسقاط واترمان الفراشي فيقدّم حلاً وسطاً مدروساً، يوازن بين دقة الشكل ودقة الحجم النسبي معاً عبر الخريطة كاملة، بدل تحسين أحدهما على حساب الآخر.</p><p><strong>وبصراحة:</strong> يبقى هذا الإسقاط، كغيره، حلاً توفيقياً لا حلاً مثالياً؛ فتمثيل كوكب كروي على شاشة مسطحة يستلزم دائماً بعض التنازلات. وقد اختير لأنه يمنح، لأغراض التعلّم ومقارنة العالم الحقيقي، صورة أكثر صدقاً من الخريطة التي اعتاد عليها معظم الناس.</p><p><strong>وما بعد الخريطة المسطحة:</strong> يضم هذا الأطلس أيضاً عرض كرة أرضية ثلاثية الأبعاد قابلة للتدوير، مفيدة لرؤية العالم كما هو فعلاً — دون أي تسطيح على الإطلاق — بالإضافة إلى أداة لمقارنة الإسقاطات تتيح لك رؤية هذه الخريطة نفسها معاد رسمها وفق إسقاطات معروفة أخرى (مثل ميركاتور)، جنباً إلى جنب، لتحكم بنفسك على المفاضلات في التشويه بدلاً من الاكتفاء بتصديق كلامنا.</p>',
                    onboardStep10Title: '🎯 وضع الاختبار',
                    onboardStep10Text: 'حوّل أي جزء من الخريطة إلى اختبار سريع. اختر مناطق وطبقات بيانات محددة، أو أنشئ أسئلة مخصصة — ثم انقر للإجابة. ممتاز لمراجعة ما تعلمته.',
                    quizMode: 'وضع الاختبار',
                    quizUnavailableOnGlobe: 'اختبار متاح فقط في وضع الخريطة المسطحة',
                    onboardStep11Title: '🌏 عرض الكرة الأرضية',
                    onboardStep11Text: 'حوّل إلى عرض الكرة الأرضية ثلاثية الأبعاد. دوّر الأرض لاستكشاف أي منطقة من أي زاوية — وتتبع الحدود والتسميات انحناء الكوكب. انقر الزر مرة أخرى للعودة إلى الخريطة المسطحة.',
                    onboardStep12Title: '📐 مقارنة الإسقاطات',
                    onboardStep12Text: 'شاهد كيف تبدو نفس الخريطة تحت إسقاطات جغرافية مختلفة جنبًا إلى جنب. افتح لوحة المقارنة لعرض الخريطة المسطحة المألوفة بجانب بدائل، واستكشف كيف يشوّه كل إسقاط الأحجام والأشكال.',
                    onboardStep13Title: '✏️ وضع الشرح',
                    onboardStep13Text: 'أضف ملاحظات ورسومات مباشرة على الخريطة: نقطة، منطقة، رسم حر، أو سهم. فعّل وضع الشرح ثم انقر على الخريطة للبدء، ويمكنك تغيير لون الرسم قبل إضافته.',
