                    onboardFinish: "Let's Explore!",
                    onboardMapGuide: '📘 Map Guide',
                    onboardingHintText: 'Click any country for details | Use the buttons above to change mode | Shift+click to compare',
                    projectionTitle: 'About This Map: The Waterman Butterfly Projection',
                    projectionBody: '<p>Every world map has to solve an impossible problem: the Earth is a sphere, but a map is flat. Flattening a globe always distorts something — size, shape, distance, or direction — no map projection can preserve all four perfectly at once.</p><p><strong>The projection you\'re looking at</strong> was created in 1996 by Steve Waterman, a mathematician who developed it from his research into the geometry of closely-packed spheres. It builds on an idea first introduced in 1909 by the architect Bernard Cahill, known as the "butterfly map." Waterman\'s version unfolds the globe along a carefully chosen geometric solid, splitting the map\'s surface at points chosen specifically so the cuts fall across oceans rather than through continents — keeping landmasses whole and uninterrupted.</p><p><strong>Why not the map most people grew up with?</strong> The Mercator projection (1569) is still the most common world map in use today, and it excels at one specific job: preserving compass directions, which made it invaluable for sea navigation for centuries. But it comes at a real cost — it badly distorts relative size the further you get from the equator. On a Mercator map, Greenland looks roughly the same size as Africa; in reality, Africa is about 14 times larger. For an educational tool meant to give an accurate sense of the world, that\'s a serious problem.</p><p><strong>Why this projection instead of other alternatives?</strong> Some projections (like Gall-Peters) fix the size problem but badly distort shapes instead, making continents look stretched and unfamiliar. The Waterman butterfly projection is a deliberate compromise, designed to keep both shape and relative size reasonably accurate at the same time, across the whole map — rather than perfecting one at the expense of the other.</p><p><strong>Worth knowing honestly:</strong> like every map projection, this one is still a compromise, not a perfect solution — representing a round planet on a flat screen always involves trade-offs. This one was chosen because, for learning and comparing the real world, it gives a more honest overall picture than the map most people are used to.</p><p><strong>Beyond the flat map:</strong> This atlas also includes a rotatable 3D globe view, useful for seeing the world the way it actually is — without any flattening at all — and a projection comparison tool that lets you see this same map redrawn under other well-known projections (like Mercator), side by side, so you can judge the distortion trade-offs for yourself rather than just take our word for it.</p>',
                    onboardStep10Title: '🎯 Quiz Mode',
                    onboardStep10Text: 'Turn any part of the map into a quick self-test. Choose specific regions and data layers to be quizzed on, or build your own custom questions — then click to answer. Great for reviewing what you\'ve learned, or for a teacher to check a class\'s understanding.',
                    quizMode: 'Quiz Mode',
                    quizUnavailableOnGlobe: 'Quiz Mode is only available in flat map view',
