                    onboardStep11Text: 'Switch to a 3D spherical globe view. Rotate the Earth to explore any region from any angle — borders and labels follow the curvature of the planet. Click the button again to return to the flat map.',
                    onboardStep12Title: '📐 Projection Comparison',
                    onboardStep12Text: 'See how the same world looks under different map projections side by side. Open the comparison panel to view the familiar flat map next to alternatives, and explore how each one distorts size and shape.',
