                    onboardWelcome: 'Добро пожаловать на карту Waterman Butterfly',
                    onboardStep1Title: '🔍 Поиск',
                    onboardStep1Text: 'Найдите любую страну по названию. Нажмите Enter, чтобы перейти к ней.',
