                    onboardStep6Title: '🗂️ Слои',
                    onboardStep6Text: 'На ПК: кнопки слоёв в верхней панели управления. На телефоне: нажмите кнопку слоёв, чтобы открыть панель. Включайте столицы, города, природные ресурсы и многое другое.',
                    onboardStep7Title: '📋 Легенда',
                    onboardStep7Text: 'Легенда слева объясняет цвета и символы на карте. Она обновляется автоматически при смене режима.',
                    onboardStep8Title: '🔍 Масштаб',
                    onboardStep8Text: 'Используйте кнопки +/- для приближения и отдаления, колесо мыши или жест щипка на мобильном.',
                    onboardStep9Title: '🌍 Сравнение стран',
                    onboardStep9Text: 'Нажмите на любую страну на карте, чтобы увидеть информацию. Shift+нажатие позволяет сравнить две страны.',
                    onboardSkip: 'Пропустить',
                    onboardNext: 'Далее →',
                    onboardFinish: 'Давайте исследуем!',
                    onboardMapGuide: '📘 Гид по карте',
                    onboardingHintText: 'Нажмите на любую страну для подробностей | Используйте кнопки выше для смены режима | Shift+нажатие для сравнения',
                    projectionTitle: 'Об этой карте: проекция Waterman «Бабочка»',
                    projectionBody: '<p>Любая карта мира должна решить невозможную задачу: Земля — сфера, а карта плоская. Развёртывание глобуса всегда искажает что-то — размер, форму, расстояние или направление — ни одна картографическая проекция не может одновременно идеально сохранить все четыре параметра.</p><p><strong>Проекция, которую вы видите</strong>, была создана в 1996 году Стивом Уотерманом, математиком, разработавшим её на основе своих исследований геометрии плотно упакованных сфер. Она основана на идее, впервые предложенной в 1909 году архитектором Бернардом Кэхиллом и известной как «карта-бабочка». Версия Уотермана разворачивает глубь вдоль тщательно выбранного геометрического тела, разделяя поверхность карты в точках, специально подобранных так, чтобы разломы проходили через океаны, а не через континенты — сохраняя материки целыми и непрерывными.</p><p><strong>Почему не карта, с которой выросли большинство людей?</strong> Проекция Меркатора (1569) по-прежнему является самой распространённой картой мира, и она превосходно справляется с одной конкретной задачей: сохранением направлений компаса, что делало её незаменимой для морской навигации на протяжении столетий. Но это имеет реальную цену — она сильно искажает относительные размеры по мере удаления от экватора. На карте Меркатора Гренландия выглядит примерно одного размера с Африкой; на самом деле Африка примерно в 14 раз больше. Для учебного пособия, призванного дать точное представление о мире, это серьёзная проблема.</p><p><strong>Почему эта проекция, а не другие альтернативы?</strong> Некоторые проекции (например, Галла-Питерса) решают проблему размера, но вместо этого сильно искажают формы, делая материки вытянутыми и неузнаваемыми. Проекция Уотермана «бабочка» — это обдуманный компромисс, сохраняющий одновременно форму и относительный размер в разумных пределах на всей карте — вместо того чтобы совершенствовать один параметр за счёт другого.</p><p><strong>Стоит знать честно:</strong> как и любая картографическая проекция, эта по-прежнему является компромиссом, а не идеальным решением — представление круглой планеты на плоском экране всегда связано с компромиссами. Эта проекция была выбрана потому, что для изучения и сравнения реального мира она даёт более честную общую картину, чем карта, к которой привыкла большинство людей.</p><p><strong>За пределами плоской карты:</strong> этот атлас также включает вращающийся 3D-глобус, полезный для того, чтобы увидеть мир таким, какой он есть на самом деле — вообще без какого-либо сплющивания, — а также инструмент сравнения проекций, который позволяет увидеть эту же карту, перерисованную по другим известным проекциям (например, Меркатора), рядом друг с другом, чтобы вы могли сами оценить компромиссы в искажениях, а не просто верить нам на слово.</p>',
                    onboardStep10Title: '🎯 Режим теста',
                    onboardStep10Text: 'Превратите любую часть карты в быстрый тест. Выберите конкретные регионы и слои данных для проверки или создайте собственные вопросы — затем нажмите для ответа. Отлично подходит для повторения изученного или для проверки знаний учителем.',
                    quizMode: 'Режим теста',
