                    onboardWelcome: 'Waterman Butterfly xartirasiga xush kelibsiz',
                    onboardStep1Title: '🔍 Qidirish',
                    onboardStep1Text: 'Istalgan mamlakatni nomi bo\'yicha toping. Enter tugmasini bosib to\'g\'ridan-to\'g\'ri o\'ting.',
                    onboardStep2Title: '🌐 Til',
                    onboardStep2Text: 'Interfeys tilini til almashtirish tugmasidan tanlang.',
                    onboardStep3Title: '🔧 Asboblar',
                    onboardStep3Text: 'Asboblar tugmasidan ulashish, tiklash, qisqa tugmalar, PDF eksport va xarita qo\'llanmasiga tez kirish uchun foydalaning.',
                    onboardStep4Title: '🎨 Xarita rejimi',
                    onboardStep4Text: 'Xaritani qanday ranglashni tanlang: din, landshaft, aholi zichligi, yog\'in, harorat, YIMI, IKI yoki tabiiy ko\'rinish.',
                    onboardStep5Title: '🎯 Filtr',
                    onboardStep5Text: 'Din bo\'yicha filtrlash: musulmon, xristian, hindu, buddist, yahudiy yoki boshqa.',
                    onboardStep6Title: '🗂️ Qatlamlar',
                    onboardStep6Text: 'Kompyuterda: qatlamlar tugmalari yuqori boshqaruv panelida. Telefonda: qatlamlar tugmasini bosib panelni oching. Poytaxtlar, shaharlar, tabiiy resurslar va boshqalarni yoqing/o\'chiring.',
                    onboardStep7Title: '📋 Ramzlar',
                    onboardStep7Text: 'Chap tomondagi ramzlar xaritadagi ranglar va belgilarni tushuntiradi. Rejim o\'zgarganda avtomatik yangilanadi.',
                    onboardStep8Title: '🔍 Masshtab',
                    onboardStep8Text: '+/- tugmalarini kattalashtirish va kichiklashtirish uchun, sichqoncha g\'ildiragini yoki mobil qurilmada ikki barmoq ishlating.',
                    onboardStep9Title: '🌍 Mamlakatlarni solishtirish',
                    onboardStep9Text: 'Mamlakat haqida ma\'lumot ko\'rish uchun xaritadagi uning ustiga bosing. Shift+bosish ikki mamlakatni solishtirish imkonini beradi.',
                    onboardSkip: 'O\'tkazish',
                    onboardNext: 'Keyingisi →',
                    onboardFinish: 'Kashf etaylik!',
                    onboardMapGuide: '📘 Xarita qo\'llanmasi',
                    onboardingHintText: 'Istalgan mamlakatga bosing — tafsilotlarni ko\'ring | Rejimni o\'zgartirish uchun yuqoridagi tugmalardan foydalaning | Solishtirish uchun Shift+bosing',
                    projectionTitle: 'Ushbu xarita haqida: Waterman Kelebek proyeksiyasi',
                    projectionBody: '<p>Har qanday jahon xaritasi imkonsiz muammoni hal qilishi kerak: Yer kura, lekin xarita tekis. Sharning tekislanishi har doim nimani distorsiya qiladi — hajm, shakl, masofa yoki yo\'nalish — hech qanday kartografik proyeksiya hamisha to\'rttasini bir vaqtda saqlab qola olmaydi.</p><p><strong>Siz qarayotgan proyeksiya</strong> 1996-yilda Stiv Uoterman tomonidan yaratilgan — bu matematik o\'z tadqiqotlari asosida yaqin joylashgan sharlarning geometriyasini rivojlantirgan. U 1909-yilda arxitektor Bernard Cahill tomonidan birinchi marta taklif qilingan g\'oya asosida qurilgan, u "kelebek xaritasi" deb tanilgan. Uoterman versiyasi globusni ehtiyotkorlik bilan tanlangan geometrik jismon orqali ochadi, xarita yuzasini okeanlar orqali o\'tadigan, qit\'alar orqali emas, deb maxsus tanlangan nuqtalarda ajratadi — qit\'alarni butun va uzluksiz saqlab qoladi.</p><p><strong>Nega ko\'pchilik o\'sgan xarita emas?</strong> Merkator proyeksiyasi (1569) hali ham eng keng tarqalgan jahon xaritasi bo\'lib, u ma\'lum bir ishni ajoyib bajaradi: kompas yo\'nalishlarini saqlash, bu uni asrlar davomida dengiz navigatsiyasi uchun qimmatli qildi. Lekin haqiqiy narx bilan keladi — u ekvatordan uzoqlashgan sayf nisbiy hajmni juda buzadi. Mercator xaritasida Grenlandiya Afrikadan taxminan bir xil ko\'rinadi; aslida Afrika taxminan 14 marta kattaroq. Dunyoning aniq tasavvurini berish uchun mo\'ljallangan ta\'lim vositasi uchun bu jiddiy muammo.</p><p><strong>Nega boshqa alternativlar emas?</strong> Ba\'zi proyeksiyalar (masalan, Gall-Peters) hajm muammosini hal qiladi, lekin o\'rniga shakllarni buzadi, qit\'alarni cho\'zilgan va tanish emas qilib ko\'rsatadi. Uoterman kelebek proyeksiyasi ongli murosadir, shakl va nisbiy hajmni bir vaqtda, butun xarita bo\'ylab qoniqarli darajada aniq saqlash uchun mo\'ljallangan — birini boshqasi hisobiga mukammallashtirish o\'rniga.</p><p><strong>Ochiq gap:</strong> har qanday kartografik proyeksiya kabi, bu ham hali murosadir, ideal emas — tekis ekranda dumaloq sayyorani ifodalash har doim murosalar talab qiladi. Bu proyeksiya tanlangan, chunki o\'rganish va haqiqiy dunyoni solishtirish uchun u ko\'pchilik o\'rgangan xaritadan ko\'ra samimiyroq umumiy rasm beradi.</p><p><strong>Tekis xaritadan tashqari:</strong> ushbu atlas shuningdek aylantiriladigan 3D globus ko\'rinishini o\'z ichiga oladi — dunyoni hech qanday tekislashsiz, aynan qanday bo\'lsa shundayligicha ko\'rish uchun foydali — va boshqa mashhur proyeksiyalar (masalan, Merkator) asosida qayta chizilgan xuddi shu xaritani yonma-yon ko\'rish imkonini beruvchi proyeksiyalarni solishtirish vositasini ham. Shunday qilib, siz distorsiya murosalarini shunchaki so\'zimizga ishonish o\'rniga o\'zingiz baholay olasiz.</p>',
                    onboardStep10Title: '🎯 Test rejimi',
                    onboardStep10Text: 'Xaritaning istalgan qismini tez testga aylantiring. Sinov uchun maxsus regionlar va ma\'lumotlar qatlamlarini tanlang yoki o\'z savollaringizni yarating — keyin javob uchun bosing. O\'rgangan narsalaringizni takrorlash uchun ajoyib.',
                    quizMode: 'Test rejimi',
                    quizUnavailableOnGlobe: 'Test rejimi faqat tekis xarita rejimida mavjud',
                    onboardStep11Title: '🌏 Sfera xarita (globus)',
                    onboardStep11Text: 'Uch o\'lchamli globus ko\'rinishiga o\'ting. Yer shari aylantirib, istalgan hududni istalgan burchakdan ko\'ring — chegaralar va nomlar sayyora egriligiga moslashadi. Yassi xaritaga qaytish uchun tugmani yana bosing.',
                    onboardStep12Title: '📐 Proyeksiyalarni taqqoslash',
                    onboardStep12Text: 'Xuddi shu xaritaning turli proyeksiyalarda qanday ko\'rinishini yonma-yon ko\'ring. Taqqoslash panelini ochib, odatiy yassi xaritani muqobillari bilan solishtiring va har bir proyeksiya o\'lcham hamda shaklni qanday buzishini ko\'ring.',
                    onboardStep13Title: '✏️ Tushuntirish rejimi',
                    onboardStep13Text: 'Xaritaga to\'g\'ridan-to\'g\'ri eslatma va chizmalar qo\'shing: nuqta, hudud, qo\'lda chizilgan rasm yoki o\'q. Tushuntirish rejimini yoqing va boshlash uchun xaritani bosing — chizma rangini oldindan tanlashingiz mumkin.',
