                    onboardWelcome: 'Bienvenido al mapa Waterman Butterfly',
                    onboardStep1Title: '🔍 Búsqueda',
                    onboardStep1Text: 'Busca cualquier país por nombre. Presiona Enter para navegar directamente a él.',
                    onboardStep2Title: '🌐 Idioma',
                    onboardStep2Text: 'Elige el idioma de la interfaz desde el botón de cambio de idioma.',
                    onboardStep3Title: '🔧 Herramientas',
                    onboardStep3Text: 'Usa el botón de herramientas para acceder rápido a compartir, reiniciar, atajos, exportar PDF y la guía del mapa.',
                    onboardStep4Title: '🎨 Modo del mapa',
                    onboardStep4Text: 'Elige cómo colorear el mapa: religión, terreno, densidad de población, lluvia, temperatura, PIB, IDH o vista natural.',
                    onboardStep5Title: '🎯 División',
                    onboardStep5Text: 'Filtra por religión: musulmán, cristiano, hindú, budista, judío u otro.',
                    onboardStep6Title: '🗂️ Capas',
                    onboardStep6Text: 'En escritorio: los botones de capas están en la barra de control superior. En móvil: toca el botón de capas para abrir el panel. Activa o desactiva capitales, ciudades, recursos naturales y más.',
                    onboardStep7Title: '📋 Leyenda',
                    onboardStep7Text: 'La leyenda a la izquierda explica los colores y símbolos del mapa. Se actualiza automáticamente al cambiar el modo.',
                    onboardStep8Title: '🔍 Zoom',
                    onboardStep8Text: 'Usa los botones +/- para acercar y alejar, la rueda del ratón o pellizcar en móvil.',
                    onboardStep9Title: '🌍 Comparar países',
                    onboardStep9Text: 'Haz clic en cualquier país del mapa para ver su información. Shift+clic permite comparar dos países lado a lado.',
                    onboardSkip: 'Omitir',
                    onboardNext: 'Siguiente →',
                    onboardFinish: '¡A explorar!',
                    onboardMapGuide: '📘 Guía del mapa',
                    onboardingHintText: 'Haz clic en cualquier país para ver detalles | Usa los botones de arriba para cambiar el modo | Mayúsculas+clic para comparar',
                    projectionTitle: 'Sobre este mapa: La proyección Waterman Mariposa',
                    projectionBody: '<p>Cada mapa del mundo tiene que resolver un problema imposible: la Tierra es una esfera, pero un mapa es plano. Aplanar un globo siempre distorsiona algo — tamaño, forma, distancia o dirección — ninguna proyección cartográfica puede preservar las cuatro perfectamente a la vez.</p><p><strong>La proyección que estás viendo</strong> fue creada en 1996 por Steve Waterman, un matemático que la desarrolló a partir de su investigación sobre la geometría de esferas compactamente apiladas. Se basa en una idea presentada por primera vez en 1909 por el arquitecto Bernard Cahill, conocida como el "mapa mariposa." La versión de Waterman despliega el globo a lo largo de un sólido geométrico cuidadosamente elegido, dividiendo la superficie del mapa en puntos escogidos específicamente para que los cortes caigan en los océanos en lugar de atravesar los continentes — manteniendo las masas terrestres enteras e ininterrumpidas.</p><p><strong>¿Por qué no el mapa con el que creció la mayoría?</strong> La proyección de Mercator (1569) sigue siendo el mapa mundial más común en uso hoy, y sobresale en un trabajo específico: preservar las direcciones de la brújula, lo que la hizo invaluable para la navegación marítima durante siglos. Pero tiene un costo real — distorsiona gravemente el tamaño relativo a medida que te alejas del ecuador. En un mapa de Mercator, Groenlandia parece aproximadamente del mismo tamaño que África; en realidad, África es unas 14 veces más grande. Para una herramienta educativa diseñada para dar una idea precisa del mundo, ese es un problema serio.</p><p><strong>¿Por qué esta proyección en lugar de otras alternativas?</strong> Algunas proyecciones (como Gall-Peters) solucionan el problema del tamaño pero distorsionan gravemente las formas, haciendo que los continentes se vean estirados y poco familiares. La proyección Waterman mariposa es un compromiso deliberado, diseñada para mantener tanto la forma como el tamaño relativo razonablemente precisos al mismo tiempo, en todo el mapa — en lugar de perfeccionar uno a costa del otro.</p><p><strong>Honestamente vale la pena saber:</strong> como toda proyección cartográfica, esta sigue siendo un compromiso, no una solución perfecta — representar un planeta redondo en una pantalla plana siempre implica concesiones. Esta proyección fue elegida porque, para aprender y comparar el mundo real, ofrece una imagen general más honesta que el mapa con el que la mayoría está acostumbrada.</p><p><strong>Más allá del mapa plano:</strong> este atlas también incluye una vista de globo 3D giratorio, útil para ver el mundo tal como realmente es — sin ningún aplanamiento — y una herramienta de comparación de proyecciones que te permite ver este mismo mapa redibujado bajo otras proyecciones conocidas (como Mercator), una al lado de la otra, para que puedas juzgar tú mismo las concesiones de distorsión en lugar de simplemente confiar en nuestra palabra.</p>',
                    onboardStep10Title: '🎯 Modo cuestionario',
                    onboardStep10Text: 'Convierte cualquier parte del mapa en un autoexamen rápido. Elige regiones y capas de datos específicas para evaluar, o crea tus propias preguntas personalizadas — luego haz clic para responder. Excelente para repasar lo que has aprendido, o para que un profesor verifique la comprensión de la clase.',
                    quizMode: 'Modo Quiz',
                    quizUnavailableOnGlobe: 'El modo quiz solo está disponible en vista de mapa plano',
                    onboardStep11Title: '🌏 Vista de globo (mapa esférico)',
                    onboardStep11Text: 'Cambia a una vista de globo tridimensional. Gira la Tierra para explorar cualquier región desde cualquier ángulo: las fronteras y los nombres siguen la curvatura del planeta. Vuelve a pulsar el botón para regresar al mapa plano.',
                    onboardStep12Title: '📐 Comparación de proyecciones',
                    onboardStep12Text: 'Observa cómo se ve el mismo mapa bajo distintas proyecciones cartográficas, lado a lado. Abre el panel de comparación para ver el mapa plano junto a alternativas y explorar cómo cada proyección distorsiona el tamaño y la forma.',
                    onboardStep13Title: '✏️ Modo de explicación',
                    onboardStep13Text: 'Añade notas y dibujos directamente sobre el mapa: un punto, un área, un dibujo a mano alzada o una flecha. Activa el modo de explicación y haz clic en el mapa para empezar; puedes elegir el color del dibujo primero.',
