    causeTranslations: {
        'Border zone disputed between Egypt and Sudan since Sudan\'s independence in 1956; Egypt claims it as part of Aswan while Sudan claims it as part of the Red Sea State.': 'Zona fronteriza disputada entre Egipto y Sudán desde la independencia de Sudán en 1956; Egipto la reclama como parte de Asuán mientras que Sudán la reclama como parte del Estado del Mar Rojo.',
        'Territorial dispute over Western Sahara between Morocco and the Polisario Front since Spain\'s withdrawal in 1975; Algeria supports the Polisario.': 'Disputa territorial sobre el Sahara Occidental entre Marruecos y el Frente Polisario desde la retirada de España en 1975; Argelia apoya al Polisario.',
        'Regional dispute since the 1947 partition of India; India claims the entire region, Pakistan claims Jammu and Kashmir, and China controls parts of Aksai Chin.': 'Disputa regional desde la partición de la India en 1947; India reclama toda la región, Pakistán reclama Jammu y Cachemira, y China controla partes de Aksai Chin.',
        'Ongoing conflict since 1948 over the West Bank, Gaza Strip, and East Jerusalem, along with refugee and settlement issues.': 'Conflicto en curso desde 1948 sobre Cisjordania, la Franja de Gaza y Jerusalén Oriental, junto con los problemas de refugiados y asentamientos.',
        'Annexed by Russia in 2014 after a controversial referendum; Ukraine and the international community still recognize it as part of Ukraine.': 'Anexada por Rusia en 2014 tras un referéndum controvertido; Ucrania y la comunidad internacional aún la reconocen como parte de Ucrania.',
        'Decades-long territorial conflict; controlled by Armenia then reclaimed by Azerbaijan in 2023 under a fragile ceasefire.': 'Conflicto territorial de décadas; controlado por Armenia y luego reclamado por Azerbaiyán en 2023 bajo un frágil alto el fuego.',
        'Region in eastern Ukraine experiencing armed conflict since 2014 between Ukrainian forces and Russia-backed separatists.': 'Región en el este de Ucrania que experimenta un conflicto armado desde 2014 entre las fuerzas ucranianas y separatistas apoyados por Rusia.',
        'Oil-rich border region disputed between Sudan and South Sudan since the south\'s independence in 2011.': 'Región fronteriza rica en petróleo disputada entre Sudán y Sudán del Sur desde la independencia del sur en 2011.',
        'Maritime dispute over islands and territorial claims in the South China Sea; China claims the nine-dash line.': 'Disputa marítima sobre islas y reclamaciones territoriales en el Mar de China Meridional; China reclama la línea de los nueve guiones.',
        'China claims Taiwan as part of its territory since the end of the Chinese Civil War in 1949; Taiwan administers itself as a de facto independent state.': 'China reclama Taiwán como parte de su territorio desde el final de la guerra civil china en 1949; Taiwán se administra como un estado de facto independiente.',
        'Israel captured the Golan Heights from Syria in 1967 and annexed it in 1981; Syria demands its return.': 'Israel capturó los Altos del Golán de Siria en 1967 y los anexó en 1981; Siria exige su devolución.',
        'Dispute between Russia and Japan over the southern Kuril Islands since World War II.': 'Disputa entre Rusia y Japón sobre las islas Kuriles del Sur desde la Segunda Guerra Mundial.',
        'Dispute over the Falkland Islands between the UK and Argentina; the 1982 war ended with a British victory.': 'Disputa sobre las Islas Malvinas entre el Reino Unido y Argentina; la guerra de 1982 terminó con una victoria británica.',
        'Spanish claim to the British overseas territory of Gibraltar since the Treaty of Utrecht 1713.': 'Reclamación española sobre el territorio británico de ultramar de Gibraltar desde el Tratado de Utrecht de 1713.',
        'Historical border disputes over the Sinai Peninsula between Egypt and Israel; returned to Egypt after the Camp David Accords of 1979.': 'Disputas fronterizas históricas sobre la Península del Sinaí entre Egipto e Israel; devuelta a Egipto después de los Acuerdos de Camp David de 1979.',
        'Turkey occupied northern Cyprus in 1974; the Turkish Republic of Northern Cyprus was unilaterally declared, with international recognition for a unified Cyprus.': 'Turquía ocupó el norte de Chipre en 1974; la República Turca del Norte de Chipre fue declarada unilateralmente, con reconocimiento internacional para un Chipre unificado.',
        'Transnistria broke away from Moldova in 1990 with Russian support; not recognized by any UN member state.': 'Transnistria se separó de Moldavia en 1990 con apoyo ruso; no reconocida por ningún estado miembro de la ONU.',
        'Abkhazia broke away from Georgia in the 1990s; Russia recognized it as an independent state after the 2008 war.': 'Abjasia se separó de Georgia en la década de 1990; Rusia la reconoció como estado independiente después de la guerra de 2008.',
        'Separatist conflict in South Ossetia from Georgia; Russia recognized it after the 2008 war.': 'Conflicto separatista en Osetia del Sur contra Georgia; Rusia la reconoció después de la guerra de 2008.',
        'Two Spanish cities on the Moroccan coast claimed by Morocco as occupied territories.': 'Dos ciudades españolas en la costa marroquí reclamadas por Marruecos como territorios ocupados.',
        'China annexed Tibet in 1950; the Tibetan government-in-exile claims independence.': 'China anexó el Tíbet en 1950; el gobierno tibetano en el exilio reclama la independencia.',
        'Dispute over Kurdish areas in Iraq between the central government and the Kurdistan Region, especially Kirkuk.': 'Disputa sobre las zonas kurdas en Irak entre el gobierno central y la Región Kurdistán, especialmente Kirkuk.'
    }
